      "الأول شد ظهره وسكت. ذهبت عينه إلى المعلومة الخاطئة، وبدأ يحسب في داخله: أأقول أم لا أقول؟ ولو قلت الآن، أينفع؟",
      "والثاني لم يسمع المعلومة أصلا. ذهبت عينه إلى الرجل المتضايق، وتحركت رجله نحوه قبل أن يعرف ماذا حدث.",
