      "فأنت لم تقل لنفسك سأنتظر قليلا. ولو رجعت بذاكرتك تبحث عن هذه اللحظة، لن تجدها. لأنها لم تحدث أصلا.",
      "الذي حدث أن الجسد وقف. وبعد ذلك قال العقل: أنا واقف لأني ما زلت أفكر.",
      "وثم شيء آخر يحدث بعد الوقفة.",
      "الموقف ينتهي عند كل الناس، ويبقى مفتوحا عندك.",
      "يعني أن الناس مضوا، والكلام انتهى، والدنيا رجعت طبيعية. وأنت ما زلت تراجع ما حدث. تعيد الكلام في رأسك، وتفكر ماذا كان ينبغي أن تقول.",
      "ويبقى هذا يعمل بداخلك حتى يأتي شيء يقول لك: انتهى، الذي فعلته كان صوابا.",
      "وآخر شيء، وهو أهمها:",
      "هذه الحركة لا تظهر في يومك العادي.",
      "فما دامت الإشارة التي تنتظرها تصلك، فأنت هادئ فعلا. وهذا ليس تمثيلا، هذا حقيقي.",
