      "ولم تتحرك عينك مع الجملة التي قيلت. تحركت مع الصوت الذي قطع.",
      "وفي الثانية نفسها عرفت أشياء لم يقلها أحد: أن الذي قطع يقدر أن يقطع، وأن الذي قوطع سكت ولا مشكلة عنده في أن يسكت، وأن الباقين رأوا ولم يعترضوا.",
      "وأنت لم تتكلم.",
      "لكنك من هذه اللحظة عرفت كيف يمضي هذا الاجتماع، وعرفت كلمة من هي التي ستغلقه."
