      "واختبار عملي يوضح هذا:",
      "فكر في آخر مرة دخلت مكانا فيه ناس لا تعرفهم.",
      "في الدقيقة الأولى، أعرفت من الممسك؟ ومن يتكلم كثيرا ولا يسمعه أحد؟ ومن يسكت وكلمته مسموعة؟",
      "ولم يخبرك أحد. أنت رأيت فقط.",
      "واختبار ثان:",
      "آخر مرة دخلت مكانا ولم تقيم أحدا فيه، متى كانت؟",
      "فإن لم تجد إجابة، فهذا في نفسه هو الإجابة.",
      "وشيء يخص هذا الباب، ولا بد أن يقال بوضوح:",
      "الذي يدفع هذا الكشاف ليس حب السيطرة.",
      "فثم شيء في جسدك لا يطمئن إلا حين تكون عارفا كيف يمضي الموقف.",
      "وانتبه إلى الكلمة: لا يطمئن. لا: لا يحب.",
      "يعني أن الحكاية أمان، لا متعة.",
      "وأثقل موضع في هذا الباب:",
      "أنت تقرأ الموازين بدقة، فتعرف مواضع كل الناس. وموضعك أنت هو الوحيد الذي ليس واضحا.",
